    badv = [i for i, c in enumerate(vlines) if any(grid[r][c] != sep for r in range(h))]

    def choose(n, bad):
        if len(bad) >= 2:
            # A block adjacent to each damaged line is retained. The surviving
            # blocks form a regular alternating sequence.
            candidates = set()
            for i in bad:
                if i + 1 < n:
                    candidates.add(i + 1)
                if i - 1 >= 0:
                    candidates.add(i - 1)
            # Prefer blocks bounded by intact separators on both sides.
            bounded = [i for i in candidates if 0 < i < n - 1]
            if len(bounded) >= 2:
                return sorted(bounded)
            return sorted(candidates)[:2]
        i = bad[0]
        if i == 0:
            return [0]
        if i == n - 1:
            return [n - 1]
        return [i - 1]

    ri, ci = choose(len(hlines), badh), choose(len(vlines), badv)
    bg = next(x for x in grid[0] if x != sep)
    width = len(ci) * (vs - 1) + len(ci) - 1
    out = []
